PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX moose: <https://moosedev.dev/kg/ontology/software-architecture/>
SELECT ?dec ?label ?status ?supersededBy WHERE {
  ?dec a moose:ArchitecturalDecision .
  OPTIONAL { ?dec rdfs:label ?label . }
  OPTIONAL { ?dec moose:hasLifecycleStatus ?status . }
  OPTIONAL { ?dec moose:supersededBy ?supersededBy . }
  FILTER(?status = "superseded" || BOUND(?supersededBy))
}
ORDER BY LCASE(STR(?label))

